<!DOCTYPE html>
<html>
<head>
<title>Billiards</title>
<style>
body {
    margin: 0;
    overflow: hidden;
    background-color: #333;
}
canvas {
    display: block;
}
#instructions {
    position: absolute;
    top: 10px;
    left: 10px;
    font-family: sans-serif;
    color: white;
    z-index: 100;
    pointer-events: none; /* Don't interfere with mouse events */
}
</style>
</head>
<body>

<canvas id="gameCanvas"></canvas>
<div id="instructions">Drag the cue ball to aim and shoot! Left click to strike.</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
window.sim = {
    W: 800,
    H: 600,
    R: 25,
    balls: [],
    reset: function(balls) {
        this.balls = balls;
    },
    step: function(dt) {
        for (let i = 0; i < this.balls.length; i++) {
            const ball = this.balls[i];

            if (ball.cue) continue;

            const x = ball.x;
            const y = ball.y;
            const vx = ball.vx;
            const vy = ball.vy;

            // Collision with walls
            if (x + vx < this.R || x + vx > this.W - this.R) vx *= -0.8; // Friction
            if (y + vy < this.R || y + vy > this.H - this.R) vy *= -0.8;

            // Ball-to-ball collision
            for (let j = i + 1; j < this.balls.length; j++) {
                const otherBall = this.balls[j];
                if (otherBall.cue) continue;

                const dx = otherBall.x - x;
                const dy = otherBall.y - y;
                const distSq = dx * dx + dy * dy;
                const ballRadius = this.R;

                if (distSq < (2 * ballRadius) * (2 * ballRadius)) { // Collision detected
                    // Calculate relative velocity
                    const vxRel = vx - otherBall.vx;
                    const vyRel = vy - otherBall.vy;

                    // Calculate distance between centers
                    const dist = Math.sqrt(dx * dx + dy * dy);

                    // Conservation of momentum
                    const m1 = 1; // Assume all balls have mass 1
                    const m2 = 1;

                    let v1x, v1y, v2x, v2y;

                    if (Math.abs(dx) > Math.abs(dy)) { // Horizontal collision
                        v1x = (m2 * otherBall.vx + m1 * vx) / (m1 + m2);
                        v1y = vy;
                        v2x = vx;
                        v2y = (m1 * otherBall.vy + m2 * vy) / (m1 + m2);
                    } else { // Vertical collision
                        v1x = vx;
                        v1y = (m2 * otherBall.vy + m1 * vy) / (m1 + m2);
                        v2x = otherBall.vx;
                        v2y = (m1 * otherBall.vy + m2 * vy) / (m1 + m2);
                    }

                    vx = v1x;
                    vy = v1y;
                    otherBall.vx = v2x;
                    otherBall.vy = v2y;
                }
            }

            ball.x += vx * dt;
            ball.y += vy * dt;
        }
    },
    state: function() {
        return this.balls.map(ball => ({
            x: ball.x,
            y: ball.y,
            vx: ball.vx,
            vy: ball.vy,
            potted: ball.potted || false,
            cue: ball.cue
        }));
    },
    shoot: function(vx, vy) {
        for (let i = 0; i < this.balls.length; i++) {
            if (this.balls[i].cue) {
                this.balls[i].vx = vx;
                this.balls[i].vy = vy;
                return;
            }
        }
    },
    pause: function() {
        window.sim.resume();
    },
    resume: function() {
        window.sim.step(0.1); // Resume with a small step
    }
};

// Initial ball setup (simplified)
window.sim.reset([
    { x: 250, y: 250, vx: 3, vy: 2, cue: true },
    { x: 550, y: 250, vx: -3, vy: 2, cue: false },
    { x: 350, y: 450, vx: 1, vy: -3, cue: false },
    { x: 650, y: 450, vx: -1, vy: -3, cue: false }
]);

let isDragging = false;
let startX, startY;
let dragVelocityX = 0;
let dragVelocityY = 0;


canvas.addEventListener('mousedown', (e) => {
    if (window.sim.balls.some(ball => ball.cue)) {
        isDragging = true;
        startX = e.clientX - canvas.offsetLeft;
        startY = e.clientY - canvas.offsetTop;
    }
});

canvas.addEventListener('mouseup', () => {
    isDragging = false;
    dragVelocityX = 0;
    dragVelocityY = 0;
});

canvas.addEventListener('mousemove', (e) => {
    if (isDragging) {
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;

        // Calculate velocity based on drag distance and time
        const deltaTime = 0.01; // Adjust for responsiveness
        dragVelocityX = dx / deltaTime;
        dragVelocityY = dy / deltaTime;
    }
});


let frameCount = 0;
function animate() {
    frameCount++;
    window.sim.step(0.02); // Smaller dt for smoother animation

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const state = window.sim.state();
    state.forEach((ball, index) => {
        const x = ball.x;
        const y = ball.y;
        const radius = window.sim.R;

        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.fillStyle = (ball.potted ? 'red' : 'white');
        ctx.fill();
        ctx.closePath();
    });

    // Draw aiming line
    if (isDragging && window.sim.balls.some(ball => ball.cue)) {
        const cueX = window.sim.balls.find(ball => ball.cue).x;
        const cueY = window.sim.balls.find(ball => ball.cue).y;

        ctx.beginPath();
        ctx.moveTo(cueX, cueY);
        ctx.lineTo(cueX + dragVelocityX * 50, cueY + dragVelocityY * 50); // Adjust line length
        ctx.strokeStyle = 'blue';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.closePath();
    }


    requestAnimationFrame(animate);
}

animate();
</script>

</body>
</html>
